def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a uniform separator row or column.
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != 0:
            top = grid[:r]
            bottom = grid[r + 1:]
            return [
                [2 if a != 0 and b != 0 else 0 for a, b in zip(x, y)]
                for x, y in zip(top, bottom)
            ]

    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0:
            return [
                [2 if grid[r][j] != 0 and grid[r][j + c + 1] != 0 else 0
                 for j in range(c)]
                for r in range(h)
            ]

    return []
